<?php require_once __DIR__.'/../config/auth.php';require_role('super_admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['toggle'])){$pdo->prepare('UPDATE branches SET is_active=1-is_active WHERE id=?')->execute([(int)$_POST['toggle']]);flash('success','Status cabang diperbarui.');}else{$id=(int)($_POST['id']??0);$data=[strtoupper(trim($_POST['code'])),trim($_POST['name']),trim($_POST['address']),trim($_POST['phone'])];if($id)$pdo->prepare('UPDATE branches SET code=?,name=?,address=?,phone=? WHERE id=?')->execute([...$data,$id]);else $pdo->prepare('INSERT INTO branches(code,name,address,phone) VALUES(?,?,?,?)')->execute($data);flash('success','Data cabang disimpan.');}redirect('/super_admin/cabang.php');}$rows=$pdo->query('SELECT b.*,(SELECT COUNT(*) FROM users u WHERE u.branch_id=b.id) users FROM branches b ORDER BY b.name')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM branches WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$pageTitle='Manajemen Cabang';$active='cabang';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2><?=$edit?'Edit':'Tambah'?> cabang</h2><form method="post" class="form-grid" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Kode<input name="code" maxlength="20" required value="<?=e($edit['code']??'')?>" placeholder="Contoh: CBG02"></label><label>Nama cabang<input name="name" required value="<?=e($edit['name']??'')?>"></label><label class="field full">Alamat<input name="address" value="<?=e($edit['address']??'')?>"></label><label class="field full">Telepon<input name="phone" value="<?=e($edit['phone']??'')?>"></label><button class="btn primary">Simpan cabang</button></form></section><section class="card"><h2>Daftar cabang</h2><div class="table-wrap"><table class="table"><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['code'])?> · <?=$r['users']?> akun</small></td><td><span class="badge <?=$r['is_active']?'':'off'?>"><?=$r['is_active']?'Aktif':'Nonaktif'?></span></td><td><div class="actions"><a class="btn soft sm" href="?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn danger sm" name="toggle" value="<?=$r['id']?>"><?=$r['is_active']?'Nonaktifkan':'Aktifkan'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
